import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def num_divisors(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    return math.prod([e + 1 for e in factors.values()])

def check_condition(k):
    if k <= 0:
        return False

    N = 2 * (k**3)
    d_Nk3 = num_divisors(N)
    target = 2 * k

    return d_Nk3 == target

