import math

def count_divisors(n):
    """Calculates the number of positive divisors d(n)."""
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if int(math.sqrt(n)) == i and n % i == 0:
                # Perfect square, count once
                count += 1
            else:
                # Count i and n/i
                count += 2
        i += 1
    return count

# Since k can be up to 5000, 2k^3 can be up to 2 * (5000)^3 = 2 * 125 * 10^9 = 2.5 * 10^{11}.
# The basic divisor function above is O(sqrt(N)), which might be slow for N up to 10^11.
# Let's use prime factorization for efficiency, as it's better suited for larger numbers in this context.

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def count_divisors_efficient(n):
    """Calculates the number of positive divisors d(n) using prime factorization."""
    if n == 1:
        return 1
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

# --- Main verification loop ---
K_MAX = 5000
solutions = []

for k in range(1, K_MAX + 1):
    N = 2 * (k**3)
    d_N = count_divisors_efficient(N)

    # Check the condition d(2k^3) = 2k
    if d_N == 2 * k:
        solutions.append(k)

print(f"Solutions found up to k={K_MAX}: {solutions}")
